"""Flask API serving sentiment analysis with a local DistilBERT SST-2 model."""
import torch
from flask import Flask, jsonify, request
from transformers import AutoModelForSequenceClassification, AutoTokenizer

MODEL_PATH = "/app/model_cache/sentiment_model"

app = Flask(__name__)

_tokenizer = None
_model = None


def _load():
    """Lazily load tokenizer and model on first request."""
    global _tokenizer, _model
    if _tokenizer is None or _model is None:
        _tokenizer = AutoTokenizer.from_pretrained(MODEL_PATH)
        _model = AutoModelForSequenceClassification.from_pretrained(MODEL_PATH)
        _model.eval()
    return _tokenizer, _model


@app.route("/sentiment", methods=["POST"])
def sentiment():
    data = request.get_json(force=True, silent=True)

    if not isinstance(data, dict):
        return jsonify({"error": "Request body must be a JSON object."}), 400

    if "text" not in data:
        return jsonify({"error": "Missing required field 'text' in request body."}), 400

    text = data["text"]
    if not isinstance(text, str):
        return jsonify({"error": "Field 'text' must be a string."}), 400

    if not text.strip():
        return jsonify({"error": "Field 'text' must be a non-empty string."}), 400

    try:
        tokenizer, model = _load()
        inputs = tokenizer(text, return_tensors="pt", truncation=True, max_length=512)
        with torch.no_grad():
            outputs = model(**inputs)
        probabilities = torch.softmax(outputs.logits, dim=-1)[0]

        labels = model.config.id2label
        if labels is None:
            labels = {0: "NEGATIVE", 1: "POSITIVE"}

        scores = {}
        for idx, prob in enumerate(probabilities):
            name = str(labels.get(idx, idx)).lower()
            scores[name] = float(prob.item())

        sentiment_label = max(scores, key=lambda k: scores[k])

        return jsonify(
            {
                "sentiment": sentiment_label,
                "confidence": {
                    "positive": scores.get("positive", 0.0),
                    "negative": scores.get("negative", 0.0),
                },
            }
        )
    except Exception as exc:  # pragma: no cover - defensive
        return jsonify({"error": f"Failed to analyze sentiment: {exc}"}), 400


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
